 [Serializable] class Report {public string instruction_id="CONNECTED-ACTION-20261012-24",status="FAIL",error,unity_version,phase,package_sha256,finalizer_sha256;public bool clip_created,clip_repeat_bytes_unchanged,clip_repeat_meta_unchanged,clip_skin_moves,clip_skin_matches_carrier;public int clip_bindings;public float clip_duration,clip_skin_max_error;public Skin source,post_import,post_apply,variant;public Vector3[] baked_true_world_positions;public bool apply,source_bytes_preserved,repeat_apply;public string[] rejection;public string[] guard_controls;public bool repeat_variant_bytes_unchanged,repeat_variant_meta_unchanged,repeat_variant_semantics_unchanged;}
 static Vector3[] Bake(GameObject asset){GameObject instance=null;Mesh m=null;try{instance=UnityEngine.Object.Instantiate(asset);var skin=instance.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();if(skin.sharedMesh.blendShapeCount!=0)throw new Exception("FinalShapesNotZero");m=new Mesh{hideFlags=HideFlags.HideAndDontSave};skin.BakeMesh(m,true);return m.vertices.Select(skin.transform.TransformPoint).ToArray();}finally{if(m!=null)UnityEngine.Object.DestroyImmediate(m);if(instance!=null)UnityEngine.Object.DestroyImmediate(instance);}}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i<0?"":a[i+1];}
 static string Work=>SessionState.GetString(W,Arg("-freshWork"));
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static Ref Id(UnityEngine.Object o){if(o==null)return null; if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out string g,out long id))throw new Exception("MissingIdentity");return new Ref{guid=g,file_id=id.ToString(System.Globalization.CultureInfo.InvariantCulture)};}
 static float[] M(Matrix4x4 m){return Enumerable.Range(0,16).Select(i=>m[i]).ToArray();}
 static Skin Capture(GameObject root){var s=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var m=s.sharedMesh;var counts=m.GetBonesPerVertex();var weights=m.GetAllBoneWeights();int k=0;var points=new Point[counts.Length];try{for(int v=0;v<counts.Length;v++){var inf=new Influence[counts[v]];for(int j=0;j<inf.Length;j++){var q=weights[k++];inf[j]=new Influence{bone=q.boneIndex,weight=q.weight,bits=BitConverter.ToInt32(BitConverter.GetBytes(q.weight),0)};}points[v]=new Point{influences=inf};}}finally{counts.Dispose();weights.Dispose();}
 return new Skin{source_root=Id(PrefabUtility.GetCorrespondingObjectFromSource(s.rootBone)),source_bones=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b))).ToArray(),source_parents=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b.parent))).ToArray(),mesh=Id(m),renderer=Id(s),root=Id(s.rootBone),bones=s.bones.Select(Id).ToArray(),bone_parents=s.bones.Select(b=>Id(b.parent)).ToArray(),materials=s.sharedMaterials.Select(Id).ToArray(),vertices=m.vertices,normals=m.normals,uv=m.uv,groups=Enumerable.Range(0,m.subMeshCount).Select(i=>new Group{topology=m.GetTopology(i).ToString(),indices=m.GetIndices(i,true)}).ToArray(),bindposes=m.bindposes.Select(b=>new Matrix{values=M(b)}).ToArray(),weights=points,matrix=M(s.transform.localToWorldMatrix),shapes=m.blendShapeCount,shape_data=Shapes(m),shape_weights=Enumerable.Range(0,m.blendShapeCount).Select(s.GetBlendShapeWeight).ToArray(),cloth=s.GetComponent<Cloth>()!=null,realization=root.GetComponentsInChildren<Transform>(true).Select(t=>{var marker=t.GetComponents<Component>().FirstOrDefault(c=>c!=null&&c.GetType().Name=="VapbRealizationMarker");return marker==null?"":EditorJsonUtility.ToJson(marker);}).Where(x=>x!="").ToArray()}; }
 static ConnectedActionConsumer(){EditorApplication.update+=Wait;AssetDatabase.importPackageCompleted+=n=>SessionState.SetBool(Done,true);CompilationPipeline.assemblyCompilationFinished+=(a,m)=>{if(m.Any(x=>x.type==CompilerMessageType.Error))SessionState.SetBool("CONNECTED24_ERRORS",true);};AssemblyReloadEvents.afterAssemblyReload+=()=>SessionState.SetBool("CONNECTED24_RELOAD",true);}
 public static void Run(){SessionState.SetString(W,Arg("-freshWork"));SessionState.SetBool(K,true);SessionState.SetBool(Done,false);SessionState.SetBool("CONNECTED24_ERRORS",false);SessionState.SetBool("CONNECTED24_RELOAD",false);AssetDatabase.ImportPackage(Arg("-freshPackage"),false);}
 static void Wait(){if(!SessionState.GetBool(K,false)||!SessionState.GetBool(Done,false)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;SessionState.SetBool(K,false);var r=new Report{unity_version=Application.unityVersion,phase=Arg("-freshPhase")};try{if(SessionState.GetBool("CONNECTED24_ERRORS",false))throw new Exception("CompileErrors");const string path="Assets/VAPBExport/manifest.json";var t=JsonUtility.FromJson<Manifest>(File.ReadAllText(path)).reference_rebind_tasks.Single();if(t.kind!="RESTORE_SOURCE_MODEL_SKIN_VARIANT_V1")throw new Exception("TaskKind");string src=AssetDatabase.GUIDToAssetPath(t.source_model_guid),edit=AssetDatabase.GUIDToAssetPath(t.model_guid);r.source=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(src));r.post_import=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));string[] protectedPaths={src,src+".meta"};var hashes=protectedPaths.Select(Hash).ToArray();var errors=new System.Collections.Generic.List<string>();Application.LogCallback log=(msg,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(msg);};Application.logMessageReceived+=log;var f=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VapbModelSkinFinalizer")).Single(x=>x!=null);r.finalizer_sha256=Hash("Assets/VAPBExport/Editor/VapbModelSkinFinalizer.cs");r.apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});Application.logMessageReceived-=log;r.rejection=errors.ToArray();r.post_apply=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));r.source_bytes_preserved=hashes.SequenceEqual(protectedPaths.Select(Hash));if(r.apply){r.variant=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path));r.baked_true_world_positions=Bake(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path));ObserveAction(t,AssetDatabase.LoadAssetAtPath<GameObject>(edit),AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path),r);string ch=Hash(t.action_clip.output_path),cm=Hash(t.action_clip.output_path+".meta");string vh=Hash(t.variant_path),vm=Hash(t.variant_path+".meta"),sem=JsonUtility.ToJson(r.variant);r.repeat_apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});r.clip_repeat_bytes_unchanged=ch==Hash(t.action_clip.output_path);r.clip_repeat_meta_unchanged=cm==Hash(t.action_clip.output_path+".meta");r.repeat_variant_bytes_unchanged=vh==Hash(t.variant_path);r.repeat_variant_meta_unchanged=vm==Hash(t.variant_path+".meta");r.repeat_variant_semantics_unchanged=sem==JsonUtility.ToJson(Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path)));}r.package_sha256=Hash(Arg("-freshPackage"));r.status="OBSERVED";}catch(Exception e){r.error=e.ToString();}Finish(r);}
 public static void ObserveWeightCopy(string asset){string work=Arg("-freshWork");if(string.IsNullOrEmpty(work)||!asset.Contains("/WeightCheck_")||!asset.EndsWith("/Model.fbx"))return;var root=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(root==null)return;var skin=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var uv=new System.Collections.Generic.List<Vector2>();skin.sharedMesh.GetUVs(1,uv);if(uv.Count==0)return;var receipts=skin.bones.Select(b=>{var c=b.GetComponents<Component>().Single(x=>x!=null&&x.GetType().Name=="VapbRealizationMarker");return (string)c.GetType().GetField("boneRealizationId").GetValue(c);}).ToArray();var record=new WeightObservation{skin=Capture(root),cp_marker=uv.ToArray(),bone_receipts=receipts,fbx_sha256=Hash(asset)};string name="weight-observation-"+Guid.NewGuid().ToString("N")+".json";File.WriteAllText(Path.Combine(work,name),JsonUtility.ToJson(record,true));}
 [Serializable] class WeightObservation{public Skin skin;public Vector2[] cp_marker;public string[] bone_receipts;public string fbx_sha256;}

 static void ObserveAction(Task task,GameObject edited,GameObject variant,Report report){
  var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(task.action_clip.output_path);if(clip==null||clip.legacy)throw new Exception("ClipMissing");report.clip_created=true;report.clip_bindings=AnimationUtility.GetCurveBindings(clip).Length;report.clip_duration=clip.length;
  var carrierPath=AssetDatabase.GUIDToAssetPath(task.action_clip.carrier_guid);var carrier=AssetDatabase.LoadAssetAtPath<GameObject>(carrierPath);var importer=(ModelImporter)AssetImporter.GetAtPath(carrierPath);string takeName=importer.defaultClipAnimations.Single().name;var take=AssetDatabase.LoadAllAssetsAtPath(carrierPath).OfType<AnimationClip>().Single(c=>c.name==takeName);
  GameObject actual=null,expected=null,native=null;Mesh a=null,b=null;
  try{
   actual=UnityEngine.Object.Instantiate(variant);expected=UnityEngine.Object.Instantiate(variant);native=UnityEngine.Object.Instantiate(carrier);
   var skinA=actual.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var skinB=expected.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var editSkin=edited.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();
   var poses=new System.Collections.Generic.Dictionary<string,Transform>();foreach(var marker in native.GetComponentsInChildren<VapbRealizationMarker>(true))if(!string.IsNullOrEmpty(marker.boneRealizationId))poses.Add(marker.boneRealizationId,marker.transform);
   if(editSkin.bones.Length!=skinB.bones.Length)throw new Exception("ActionBoneCount");
   a=new Mesh();b=new Mesh();skinA.BakeMesh(a,true);var rest=a.vertices.Select(skinA.transform.TransformPoint).ToArray();report.clip_skin_matches_carrier=true;
   foreach(float fraction in new[]{0f,0.5f,1f}){
    clip.SampleAnimation(actual,clip.length*fraction);take.SampleAnimation(native,take.length*fraction);
    // SourceKind Apply verifies edited/source Bone order and exact UID mapping; source counterpart refs are captured separately.
    for(int i=0;i<editSkin.bones.Length;i++){var id=editSkin.bones[i].GetComponent<VapbRealizationMarker>().boneRealizationId;var pose=poses[id];skinB.bones[i].localPosition=pose.localPosition;skinB.bones[i].localRotation=pose.localRotation;skinB.bones[i].localScale=pose.localScale;}
    skinA.BakeMesh(a,true);skinB.BakeMesh(b,true);var x=a.vertices.Select(skinA.transform.TransformPoint).ToArray();var y=b.vertices.Select(skinB.transform.TransformPoint).ToArray();if(x.Length!=y.Length)throw new Exception("ActionLayout");
    for(int i=0;i<x.Length;i++){float error=(x[i]-y[i]).magnitude;report.clip_skin_max_error=Mathf.Max(report.clip_skin_max_error,error);if(error>=0.0001f)report.clip_skin_matches_carrier=false;if((x[i]-rest[i]).magnitude>0.001f)report.clip_skin_moves=true;}
   }
  }finally{if(a!=null)UnityEngine.Object.DestroyImmediate(a);if(b!=null)UnityEngine.Object.DestroyImmediate(b);foreach(var o in new[]{actual,expected,native})if(o!=null)UnityEngine.Object.DestroyImmediate(o);}
 }
 static void Finish(Report r){SessionState.SetBool(K,false);File.WriteAllText(Path.Combine(Work,"native.json"),JsonUtility.ToJson(r,true));EditorApplication.Exit(r.status=="FAIL"?1:0);}
}

